-- Diagnóstico novo, somente leitura. Não instala manutenção nem chama emissores.
BEGIN READ ONLY; SET LOCAL statement_timeout='10s'; SET LOCAL lock_timeout='1s';
DO $diagnostico$ BEGIN
 IF to_regclass('public.nina_settings') IS NULL OR to_regclass('public.send_queue') IS NULL THEN RAISE EXCEPTION 'MANUTENCAO_ORIGEM_RECUSADA'; END IF;
 IF to_regclass('cron.job') IS NULL THEN RAISE EXCEPTION 'MANUTENCAO_CRON_INDISPONIVEL'; END IF;
END $diagnostico$;
WITH resumo AS (WITH alvos AS (SELECT c.oid,n.nspname,c.relname,c.relowner,c.relrowsecurity,c.relforcerowsecurity FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND n.nspname||'.'||c.relname IN ('auth.users','storage.buckets','storage.objects','public.appointments','public.automation_executions','public.automation_logs','public.automation_rules','public.automation_scheduled','public.contact_cooldowns','public.contacts','public.conversation_activities','public.conversation_states','public.conversations','public.deal_activities','public.deals','public.message_grouping_queue','public.message_processing_queue','public.messages','public.nina_processing_queue','public.nina_settings','public.notifications','public.orders','public.pipeline_stages','public.product_catalog_audit','public.profiles','public.send_queue','public.support_cases','public.system_settings','public.tag_definitions','public.team_business_hours','public.team_functions','public.team_holidays','public.team_members','public.teams','public.user_roles','public.webhook_events','public.whatsapp_templates')), itens AS (
 SELECT nspname||'.'||relname nome,md5(jsonb_build_array(pg_catalog.pg_get_userbyid(relowner),relrowsecurity,relforcerowsecurity,(SELECT jsonb_agg(jsonb_build_array(a.attnum,a.attname,pg_catalog.format_type(a.atttypid,a.atttypmod),a.attnotnull) ORDER BY a.attnum) FROM pg_catalog.pg_attribute a WHERE a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped))::text) hash FROM alvos t
 UNION ALL SELECT n.nspname||'.'||p.proname||'('||pg_catalog.pg_get_function_identity_arguments(p.oid)||')',md5(pg_catalog.pg_get_functiondef(p.oid)) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('claim_send_queue_batch','claim_nina_processing_batch','claim_message_processing_batch')) SELECT md5(string_agg(nome||':'||hash,'|' ORDER BY nome)),(SELECT count(*) FROM alvos) FROM itens) SELECT jsonb_build_object('versao',1,'banco',current_database(),'catalogoHash',resumo.md5,'tabelas',resumo.count,'cronDisponivel',true,'configuracoes',(SELECT count(*) FROM public.nina_settings),'permissoesSuficientes',has_table_privilege(current_user,'public.nina_settings','UPDATE') AND has_table_privilege(current_user,'public.automation_rules','UPDATE') AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_roles r ON r.rolname=current_user WHERE (n.nspname||'.'||c.relname IN ('auth.users','storage.buckets','storage.objects','public.appointments','public.automation_executions','public.automation_logs','public.automation_rules','public.automation_scheduled','public.contact_cooldowns','public.contacts','public.conversation_activities','public.conversation_states','public.conversations','public.deal_activities','public.deals','public.message_grouping_queue','public.message_processing_queue','public.messages','public.nina_processing_queue','public.nina_settings','public.notifications','public.orders','public.pipeline_stages','public.product_catalog_audit','public.profiles','public.send_queue','public.support_cases','public.system_settings','public.tag_definitions','public.team_business_hours','public.team_functions','public.team_holidays','public.team_members','public.teams','public.user_roles','public.webhook_events','public.whatsapp_templates') OR c.oid='cron.job'::regclass) AND c.relrowsecurity AND NOT(r.rolsuper OR r.rolbypassrls OR (c.relowner=r.oid AND NOT c.relforcerowsecurity))) AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['auth.users','storage.buckets','storage.objects','public.appointments','public.automation_executions','public.automation_logs','public.automation_rules','public.automation_scheduled','public.contact_cooldowns','public.contacts','public.conversation_activities','public.conversation_states','public.conversations','public.deal_activities','public.deals','public.message_grouping_queue','public.message_processing_queue','public.messages','public.nina_processing_queue','public.nina_settings','public.notifications','public.orders','public.pipeline_stages','public.product_catalog_audit','public.profiles','public.send_queue','public.support_cases','public.system_settings','public.tag_definitions','public.team_business_hours','public.team_functions','public.team_holidays','public.team_members','public.teams','public.user_roles','public.webhook_events','public.whatsapp_templates']) alvo WHERE NOT has_table_privilege(current_user,alvo,'SELECT') OR NOT has_table_privilege(current_user,alvo,'TRIGGER')),'coletorLeituraExistente',to_regprocedure('donatella_migracao.coletor_autorizado()') IS NOT NULL AND to_regprocedure('donatella_migracao.chave(jsonb,text[])') IS NOT NULL AND to_regprocedure('donatella_migracao.projetar(text,jsonb)') IS NOT NULL)||(SELECT jsonb_build_object('cronJobs',count(*),'cronHash',md5(coalesce(string_agg(jobid::text||':'||md5(to_jsonb(j)::text),'|' ORDER BY jobid),'')),'podeAlterarCron',has_table_privilege(current_user,'cron.job','UPDATE') OR (CASE WHEN to_regprocedure('cron.alter_job(bigint,text,text,text,text,boolean)') IS NOT NULL THEN has_function_privilege(current_user,to_regprocedure('cron.alter_job(bigint,text,text,text,text,boolean)'),'EXECUTE') AND ((SELECT rolsuper FROM pg_catalog.pg_roles WHERE rolname=current_user) OR NOT EXISTS(SELECT 1 FROM cron.job j WHERE j.database=current_database() AND to_jsonb(j)->>'username' IS DISTINCT FROM current_user)) ELSE false END),'cronMecanismo',CASE WHEN (CASE WHEN to_regprocedure('cron.alter_job(bigint,text,text,text,text,boolean)') IS NOT NULL THEN has_function_privilege(current_user,to_regprocedure('cron.alter_job(bigint,text,text,text,text,boolean)'),'EXECUTE') AND ((SELECT rolsuper FROM pg_catalog.pg_roles WHERE rolname=current_user) OR NOT EXISTS(SELECT 1 FROM cron.job j WHERE j.database=current_database() AND to_jsonb(j)->>'username' IS DISTINCT FROM current_user)) ELSE false END) THEN 'alter_job' ELSE 'tabela' END) FROM cron.job j WHERE database=current_database()) AS preflight FROM resumo;
ROLLBACK;
